update hb_org_info
set hb_org_name = #{hbOrgName,jdbcType=VARCHAR},
  hb_org_status = #{hbOrgStatus,jdbcType=INTEGER},
  create_time = #{createTime,jdbcType=TIMESTAMP},
  create_by = #{createBy,jdbcType=VARCHAR}
where id = #{id,jdbcType=BIGINT}

mapper.select:
select ipi.id id, ipi.hb_org_name hbOrgName, ipi.hb_org_status hbOrgStatus, ipi.create_by createBy, ipi.create_time createTime,IFNULL(ip.SS,0) num from (select id,hb_org_name,hb_org_status,create_by,create_time from hb_org_info) AS ipi LEFT JOIN (select hb_org_id,COUNT(1) as SS from hb_user_info GROUP BY hb_org_id) AS ip on ipi.id=ip.hb_org_id
and ipi.hb_org_status = #{hbOrgStatus,jdbcType=INTEGER}
order by ipi.id desc limit #{page}, #{pageSize}

